import { isFunction, omitEmpty } from '@splendidlabz/utils'
import {
  Focusable,
  addListeners,
  getSelfIndex,
  isArrowKey,
  removeListeners,
} from '@splendidlabz/utils/dom'

/**
 * Reads the --placement CSS custom property from a node's computed style.
 * Falls back to 'top' if not set.
 */
export function readPlacement(node) {
  const value = getComputedStyle(node).getPropertyValue('--placement').trim()
  return value || 'top'
}

// ========================
// Shared State
// ========================
const tabs = $state([])

export function getTab(id) {
  return tabs.find(t => t.id === id)
}

export function initTab({ id, state = {}, nodes = {}, options = {} }) {
  const tab = getTab(id)
  if (!tab) {
    tabs.push({ id, state, nodes, options })
  } else {
    tab.state = { ...tab.state, ...omitEmpty(state) }
    tab.nodes = { ...tab.nodes, ...omitEmpty(nodes, { shallow: true }) }
    tab.options = { ...tab.options, ...omitEmpty(options) }
  }

  return getTab(id)
}

// ========================
// Default Values
// ========================
export const DEFAULT_TABLIST_OPTIONS = {
  state: {
    placement: 'top', // top, left, right
  },
  options: {
    useHash: false,
    scrollIntoView: false,
    scrollIntoViewOnLoad: true,
    scrollBehaviour: 'smooth', // smooth, auto
    loop: false,
    autoplay: false,
    autoplayInterval: 3000,
    onTabChange: null,
  },
}

export const TABLIST_OPTION_KEYS = Object.keys({
  ...DEFAULT_TABLIST_OPTIONS.state,
  ...DEFAULT_TABLIST_OPTIONS.options,
})

export function tablist(node, props) {
  const targetId = node.getAttribute('target')

  // The filter allows us to nest tabs in tabs
  const tablistItems = Array.from(node.querySelectorAll('[role="tab"]')).filter(
    tab => tab.closest('.tablist') === node,
  )
  let activeTabIndex
  activeTabIndex = tablistItems.findIndex(tab =>
    tab.hasAttribute('aria-selected'),
  )
  if (activeTabIndex === -1) activeTabIndex = 0

  const tabInfo = {
    id: targetId,
    state: {
      ...DEFAULT_TABLIST_OPTIONS.state,
      placement: readPlacement(node),
      activeTabIndex,
      length: tablistItems.length,
    },
    nodes: { tablist: node, tablistItems },
    options: {
      ...DEFAULT_TABLIST_OPTIONS.options,
      ...omitEmpty(props.options),
    },
  }

  const Tab = initTab(tabInfo)

  setInitialState(Tab)

  // Add listeners
  const listeners = [
    {
      event: 'click',
      node,
      handler: handleClick,
    },
    {
      event: 'keydown',
      node,
      handler: handleKeydown,
    },
  ]

  addListeners(listeners)

  // Re-read placement from CSS on resize (handles responsive breakpoints)
  function handleResize() {
    const newPlacement = readPlacement(node)
    if (newPlacement !== Tab.state.placement) {
      updatePlacement(Tab, newPlacement)
    }
  }

  window.addEventListener('resize', handleResize)

  const { autoplay } = Tab.options
  if (autoplay) setAutoplayInterval(Tab)

  return {
    destroy() {
      removeListeners(listeners)
      window.removeEventListener('resize', handleResize)
    },
  }

  function handleClick(event) {
    const tab = event.target.closest('[role="tab"]')
    if (!tab) return
    const { tablistItems } = Tab.nodes

    const index = tablistItems.findIndex(t => t === tab)
    selectTab(Tab, index)
  }

  function handleKeydown(event) {
    const { placement } = Tab.state
    const { key } = event
    if (isArrowKey(key)) {
      event.preventDefault() // prevents scrolling

      if (placement === 'top') {
        if (key === 'ArrowLeft') selectPrevTab(Tab)
        if (key === 'ArrowRight') selectNextTab(Tab)
        if (key === 'ArrowDown') focusOnTabpanel(Tab)
      }

      if (placement === 'left') {
        if (key === 'ArrowUp') selectPrevTab(Tab)
        if (key === 'ArrowDown') selectNextTab(Tab)
        if (key === 'ArrowRight') focusOnTabpanel(Tab)
      }

      if (placement === 'right') {
        if (key === 'ArrowUp') selectPrevTab(Tab)
        if (key === 'ArrowDown') selectNextTab(Tab)
        if (key === 'ArrowLeft') focusOnTabpanel(Tab)
      }
    }
  }
}

export function tabpanels(node, props) {
  const tabpanelsId = node.id

  // The filter allows us to nest tabs in tabs
  const tabpanelItems = Array.from(
    node.querySelectorAll('[role="tabpanel"]'),
  ).filter(tab => tab.closest('.tabpanels') === node)

  const existingTab = getTab(tabpanelsId)
  let activeTabIndex
  if (existingTab?.nodes?.tablist != null) {
    activeTabIndex = existingTab.state.activeTabIndex ?? 0
  } else {
    activeTabIndex = tabpanelItems.findIndex(
      tabpanel => !tabpanel.hasAttribute('hidden'),
    )
    if (activeTabIndex === -1) activeTabIndex = 0
  }

  const Tab = initTab({
    id: tabpanelsId,
    state: { activeTabIndex, length: tabpanelItems.length },
    nodes: { tabpanels: node, tabpanelItems },
  })

  setInitialState(Tab)

  // Add listeners
  const listeners = [
    {
      event: 'keydown',
      node,
      handler: handleKeydown,
    },
  ]

  addListeners(listeners)

  return {
    destroy() {
      removeListeners(listeners)
    },
  }

  function handleKeydown(event) {
    if (!event.target.matches('.tabpanel')) return

    if (event.target.closest('.tabpanels') !== node) return

    const { placement } = Tab.state
    const { key } = event

    if (isArrowKey(key)) {
      event.preventDefault() // prevents scrolling
      event.stopPropagation() // Prevents nested tabpanel from focusing on external tabpanel

      if (placement === 'top' && key === 'ArrowUp') focusOnTab(Tab)
      if (placement === 'left' && key === 'ArrowLeft') focusOnTab(Tab)
      if (placement === 'right' && key === 'ArrowRight') focusOnTab(Tab)

      // The following would be to focus on the first content item.
      // Not necessary, but would be nice and seems like a good idea.
      if (key === 'ArrowDown') focusOnTabpanelContent(event.target)
    }
  }
}

function setInitialState(Tab) {
  // Wait until component is fully initialized before proceeding.
  const { tablist, tabpanels } = Tab.nodes
  if (!(tablist && tabpanels)) return

  const { hash } = window.location

  // Standard initialization
  if (!hash) {
    selectTab(Tab, Tab.state.activeTabIndex, { shouldFocusOnTab: false })
    return
  }

  // Hash-based initiation
  // Activates tab and tabpanel if hashed ID is within the tabpanel.
  const element = document.querySelector(hash)
  const inTabpanel = element?.closest('.tabpanels') === tabpanels
  if (!inTabpanel) return

  const closestTabpanel = element.closest('.tabpanel')
  const index = getSelfIndex(closestTabpanel)
  selectTab(Tab, index, { shouldUpdateHash: false, shouldScroll: false })

  // Scroll to content
  if (element !== closestTabpanel)
    element.scrollIntoView({ behavior: Tab.options.scrollBehaviour })
  else {
    // Scrolls to Tablist
    if (Tab.options.scrollIntoViewOnLoad) scrollIntoView(Tab)
    else scrollIntoView(Tab, 'instant')
  }
}

export function selectTab(
  Tab,
  index,
  {
    shouldFocusOnTab = true,
    shouldUpdateHash = true,
    shouldScroll = true,
  } = {},
) {
  Tab.state.activeTabIndex = index

  setActiveTab(Tab)
  setActivePanel(Tab)
  if (shouldFocusOnTab) focusOnTab(Tab)

  const activeTab = Tab.nodes.tablistItems[index]
  const activePanel = Tab.nodes.tabpanelItems[index]
  const { onTabChange } = Tab.options

  if (isFunction(onTabChange)) {
    onTabChange({ Tab, activeTab, activePanel })
  }

  // TODO: Does this break if we don't include splendidLabz/layout in the build?
  // If it does, we need to import layout scripts with await import.
  // Then we'll have to turn `selectTab` into an async function and manage the rest accordingly
  // if (Tab.options.runLayoutScripts) {
  //   setTimeout(_ => layoutScripts(activePanel), 0)
  // }

  const { useHash, autoplay } = Tab.options

  // Update the URL hash url if link to tab is active
  if (useHash && shouldUpdateHash) {
    const activeTabpanelId = Tab.nodes.tabpanelItems[index].id
    history.pushState(null, null, `#${activeTabpanelId}`)
    if (shouldScroll && Tab.options.scrollIntoView) scrollIntoView(Tab)
  }

  // Reset progression interval ID
  if (autoplay) {
    clearInterval(Tab.state.autoplayID)
    setAutoplayInterval(Tab)
  }
}

function scrollIntoView(Tab, behaviour) {
  const { scrollBehaviour } = Tab.options
  Tab.nodes.tablist.scrollIntoView({
    behavior: behaviour || scrollBehaviour,
  })
}

export function selectNextTab(Tab) {
  const { activeTabIndex, length } = Tab.state
  const { loop } = Tab.options

  let nextIndex = activeTabIndex + 1
  if (nextIndex >= length) {
    if (loop) nextIndex = 0
    else return
  }

  selectTab(Tab, nextIndex)
}
export function selectPrevTab(Tab) {
  const { activeTabIndex, length } = Tab.state
  const { loop } = Tab.options

  let prevIndex = activeTabIndex - 1
  if (prevIndex < 0) {
    if (loop) prevIndex = length - 1
    else return
  }

  selectTab(Tab, prevIndex)
}

export function focusOnTab(Tab) {
  const { activeTabIndex } = Tab.state
  const { tablistItems } = Tab.nodes
  tablistItems[activeTabIndex].focus()
}

export function focusOnTabpanel(Tab) {
  const { activeTabIndex } = Tab.state
  const { tabpanelItems } = Tab.nodes
  tabpanelItems[activeTabIndex].focus()
}

export function focusOnTabpanelContent(Tabpanel) {
  const focusables = Focusable(Tabpanel)
  if (focusables.length) focusables.first.focus()
}

function setActiveTab(Tab) {
  const { activeTabIndex } = Tab.state
  const { tablistItems } = Tab.nodes

  tablistItems.forEach((tab, index) => {
    const isActiveTab = index === activeTabIndex
    if (isActiveTab) {
      tab.setAttribute('aria-selected', 'true')
      tab.setAttribute('tabindex', '0')
    } else {
      tab.removeAttribute('aria-selected')
      tab.setAttribute('tabindex', '-1')
    }
  })
}

function setActivePanel(Tab) {
  const { activeTabIndex } = Tab.state
  const { tabpanelItems } = Tab.nodes

  tabpanelItems.forEach((panel, index) => {
    const isActiveTab = index === activeTabIndex
    if (isActiveTab) {
      panel.removeAttribute('hidden')
      panel.setAttribute('tabindex', '0')
    } else {
      panel.setAttribute('hidden', 'true')
      panel.removeAttribute('tabindex')
    }
  })
}

export function updatePlacement(Tab, placement) {
  Tab.state.placement = placement
}

function setAutoplayInterval(Tab) {
  const { autoplayInterval } = Tab.options
  const intervalID = setInterval(() => {
    selectNextTab(Tab)
  }, autoplayInterval)
  Tab.state.autoplayID = intervalID
}
